"use client";

import { useState } from 'react';
import { Search, Info, ExternalLink, RefreshCw } from 'lucide-react';
import InvestigationGraph from './InvestigationGraph';
import { GraphData } from '@/lib/mockData'; // We'll keep the types from here for now

export default function Dashboard() {
  const [address, setAddress] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [data, setData] = useState<GraphData | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!address.trim()) return;
    
    setIsSearching(true);
    setError(null);
    setData(null);

    try {
      // 1. Create Investigation & Fetch Transactions
      const createRes = await fetch('/api/investigations', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ address })
      });

      if (!createRes.ok) {
        throw new Error((await createRes.json()).error || 'Failed to initiate trace');
      }

      const { investigationId } = await createRes.json();

      // 2. Fetch Summary
      const summaryRes = await fetch(`/api/investigations/${investigationId}`);
      if (!summaryRes.ok) throw new Error('Failed to fetch summary');
      const summaryData = await summaryRes.json();

      // 3. Fetch Graph
      const graphRes = await fetch(`/api/investigations/${investigationId}/graph`);
      if (!graphRes.ok) throw new Error('Failed to fetch graph data');
      const graphData = await graphRes.json();

      // Combine into expected UI format
      setData({
        summary: {
          confidenceScore: summaryData.topCandidate?.score || 0,
          nearestVasp: summaryData.topCandidate?.name || 'Unknown / Insufficient Evidence',
          hopDistance: summaryData.topCandidate?.hopDistance || 0,
          clusterSize: summaryData.clusterSize || 0,
        },
        nodes: graphData.nodes || [],
        edges: graphData.edges || []
      });

    } catch (err: any) {
      console.error(err);
      setError(err.message || 'An unexpected error occurred.');
    } finally {
      setIsSearching(false);
    }
  };

  const handleClear = () => {
    setAddress('');
    setData(null);
    setError(null);
  };

  return (
    <div className="flex-1 flex flex-col h-full bg-slate-950 p-6 overflow-hidden">
      
      {/* Top Control Bar */}
      <div className="flex flex-col gap-2 mb-6 shrink-0">
        <form onSubmit={handleSearch} className="flex-1 max-w-2xl flex items-center relative">
          <div className="absolute left-3 text-slate-500">
            <Search size={20} />
          </div>
          <input 
            type="text" 
            placeholder="Enter Bitcoin address (e.g., bc1q...)"
            className="w-full bg-slate-900 border border-slate-700 text-white rounded-lg pl-10 pr-32 py-3 focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500 shadow-inner"
            value={address}
            onChange={(e) => setAddress(e.target.value)}
          />
          <div className="absolute right-2 flex gap-2">
            {data && (
              <button 
                type="button" 
                onClick={handleClear}
                className="px-3 py-1.5 text-xs text-slate-400 hover:text-white"
              >
                Clear
              </button>
            )}
            <button 
              type="submit"
              disabled={isSearching || !address.trim()}
              className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-1.5 rounded-md text-sm font-medium transition-colors disabled:opacity-50 flex items-center gap-2"
            >
              {isSearching ? <RefreshCw size={16} className="animate-spin" /> : 'Trace'}
            </button>
          </div>
        </form>
        {error && <p className="text-red-500 text-sm">{error}</p>}
      </div>

      {/* Main Content Area */}
      <div className="flex-1 flex gap-6 overflow-hidden">
        
        {/* Left Panel: Summary */}
        <div className="w-80 shrink-0 flex flex-col gap-4 overflow-y-auto pr-2 pb-4">
          <div className="bg-slate-900 border border-slate-800 rounded-lg p-5">
            <h2 className="text-lg font-semibold text-white mb-4 flex items-center gap-2">
              <Info size={18} className="text-blue-500" />
              Attribution Summary
            </h2>
            
            {data ? (
              <div className="space-y-4">
                <div>
                  <p className="text-xs text-slate-500 font-medium uppercase tracking-wider mb-1">Target Address</p>
                  <p className="text-sm font-mono text-slate-300 break-all">{address}</p>
                </div>
                
                <div className="pt-4 border-t border-slate-800">
                  <p className="text-xs text-slate-500 font-medium uppercase tracking-wider mb-1">Candidate VASP</p>
                  <div className="flex items-center justify-between">
                    <p className={`text-md font-bold ${data.summary.nearestVasp !== 'Unknown / Insufficient Evidence' ? 'text-emerald-400' : 'text-slate-400'}`}>{data.summary.nearestVasp}</p>
                    {data.summary.nearestVasp !== 'Unknown / Insufficient Evidence' && <ExternalLink size={14} className="text-slate-500 cursor-pointer hover:text-white" />}
                  </div>
                </div>
                
                <div className="grid grid-cols-2 gap-3 pt-4 border-t border-slate-800">
                  <div className="bg-slate-950 p-3 rounded border border-slate-800">
                    <p className="text-xs text-slate-500 mb-1">Confidence Score</p>
                    <p className="text-xl font-bold text-white">{data.summary.confidenceScore}/100</p>
                  </div>
                  <div className="bg-slate-950 p-3 rounded border border-slate-800">
                    <p className="text-xs text-slate-500 mb-1">Hop Distance</p>
                    <p className="text-xl font-bold text-white">{data.summary.hopDistance}</p>
                  </div>
                </div>

                <div className="pt-4 border-t border-slate-800">
                   <p className="text-xs text-slate-500 mb-2">Evidence Signals</p>
                   <div className="space-y-2">
                     <div className="flex justify-between items-center bg-slate-950 px-3 py-2 rounded text-sm">
                       <span className="text-slate-400">Cluster Size</span>
                       <span className="font-semibold text-white">{data.summary.clusterSize} addresses</span>
                     </div>
                   </div>
                </div>

              </div>
            ) : (
              <div className="text-sm text-slate-500 h-40 flex items-center justify-center text-center">
                Awaiting investigation data. Enter an address to trace.
              </div>
            )}
          </div>
        </div>

        {/* Right Panel: Graph Visualization */}
        <div className="flex-1 flex flex-col min-w-0 h-full">
           <InvestigationGraph data={data} />
        </div>

      </div>
    </div>
  );
}
